def validate_return(result, label, max_tokens=32):
    """Validate return type and bounds. Returns list of error strings."""
    errors = []
    if isinstance(result, list):
        if len(result) > max_tokens:
            errors.append(f"list length {len(result)} exceeds max {max_tokens}")
        for i, tok in enumerate(result):
            if not isinstance(tok, int):
                errors.append(f"token {i} is not int: {type(tok)}")
    elif isinstance(result, dict):
        if "text" not in result:
            errors.append("dict missing 'text' key")
        elif not isinstance(result["text"], str):
            errors.append(f"'text' is not str: {type(result['text'])}")
        if len(result.get("text", "")) > max_tokens * 20:
            errors.append(f"text likely exceeds {max_tokens} tokens")
    else:
        errors.append(f"unknown return type: {type(result)}")
    return errors


